Tmr_Irq tmr_irq_create( Tmr_Irq_Func tmr_irq_func )
{	
    Tmr_Irq tmr_irq = NULL ;

	CRITICAL ;

	C_ENTER ;
	{
		tmr_irq_init();
	        
	    if (tmr_irq_count < TMR_IRQ_COUNT)
		{
			tmr_irq = (Tmr_Irq)os_mem_request (sizeof (tmr_irq)) ;	
				
			tmr_irq->index          = tmr_irq_count;
	        tmr_irq->service_vector = tmr_irq_func ;
	
	        tmr_irq_table[ tmr_irq_count ++ ] = tmr_irq ;			
		}
	}
	C_LEAVE;
	    
    return tmr_irq ;
}

